const EQUIPMENT = {
  omori:{weapon:'Shiny Knife',charm:'Seer Goggles',atk:5,hp:1,def:1,spd:0,luck:3,hit:300},
  aubrey:{weapon:'Comet Hammer',charm:'Flashlight',atk:6,hp:0,def:4,spd:0,luck:2,hit:100},
  kel:{weapon:'Rubber Ball',charm:'Bubble Wrap',atk:3,hp:0,def:3,spd:0,luck:0,hit:100},
  hero:{weapon:'Spatula',charm:'TV Remote',atk:4,hp:5,def:2,spd:0,luck:0,hit:100}
};
export const DEFAULT_STATE={levels:{omori:8,aubrey:8,kel:7,hero:7},current:{omori:{hp:72,juice:46},aubrey:{hp:81,juice:27},kel:{hp:58,juice:53},hero:{hp:66,juice:41}}};
export const PARTY = PARTY_LEVELS.map(p=>{const level=DEFAULT_STATE.levels[p.id],i=level-1,eq=EQUIPMENT[p.id],cur=DEFAULT_STATE.current[p.id];return{id:p.id,name:p.name[0]+p.name.slice(1).toLowerCase(),level,hp:cur.hp,maxHp:p.hp[i]+eq.hp,juice:cur.juice,maxJuice:p.juice[i],atk:p.atk[i]+eq.atk,def:p.def[i]+eq.def,spd:p.spd[i]+eq.spd,luck:p.luck[i]+eq.luck,hit:eq.hit,weapon:eq.weapon,charm:eq.charm}});

export const ENCOUNTERS = {
  spaceboy:{name:'Space Ex-Boyfriend',enemies:[{name:'Space Ex-Boyfriend',hp:1350,atk:15,def:16,spd:25,kind:'spaceboy'}]},
  download:{name:'Download Window',enemies:[{name:'Download Window',hp:600,atk:10,def:5,spd:1,kind:'download'}]},
  bunnies:{name:'2× Space Bunny',enemies:[{name:'Space Bunny A',hp:105,atk:12,def:7,spd:10,kind:'bunny'},{name:'Space Bunny B',hp:105,atk:12,def:7,spd:10,kind:'bunny'}]}
};

const POLICY = {
  suboptimal:{name:'Suboptimal',heal:.18,item:.08,skill:.13,follow:.72,headbutt:.18,focus:.55},
  decent:{name:'Decent',heal:.42,item:.24,skill:.48,follow:.50,headbutt:.22,focus:.84},
  best:{name:'Best found',heal:.55,item:.50,skill:.78,follow:.30,headbutt:.26,focus:.98},
  custom:{name:'Someone',heal:.14,item:.06,skill:.28,follow:.80,headbutt:.27,focus:.91}
};

function rng32(seed){let a=seed>>>0;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function pick(rng,arr){return arr[Math.floor(rng()*arr.length)]}
function variance(rng,v){return Math.max(1,Math.round(v*(.8+rng()*.4)))}
function alive(list){return list.filter(x=>x.hp>0)}
function lowest(list){return alive(list).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0]}
function scaleParty(levels,current){return PARTY_LEVELS.map(p=>{const level=Math.max(1,Math.min(50,levels?.[p.id]||DEFAULT_STATE.levels[p.id])),i=level-1,eq=EQUIPMENT[p.id],maxHp=p.hp[i]+eq.hp,maxJuice=p.juice[i],cur=current?.[p.id];return{id:p.id,name:p.name[0]+p.name.slice(1).toLowerCase(),level,maxHp,hp:Math.max(0,Math.min(maxHp,cur?.hp??maxHp)),maxJuice,juice:Math.max(0,Math.min(maxJuice,cur?.juice??maxJuice)),atk:p.atk[i]+eq.atk,def:p.def[i]+eq.def,spd:p.spd[i]+eq.spd,luck:p.luck[i]+eq.luck,hit:eq.hit,weapon:eq.weapon,charm:eq.charm}})}
function makeBattle(setup,rng){
  const party=scaleParty(setup.levels,setup.current);
  const enemies=ENCOUNTERS[setup.encounter].enemies.map((e,i)=>({...e,id:`e${i}`,maxHp:e.hp}));
  const inv=setup.inventory==='standard'?{candy:6,juice:3,jam:2}:setup.inventory==='lean'?{candy:2,juice:1,jam:1}:{candy:0,juice:0,jam:0};
  return{party,enemies,inv,energy:3,turn:0,rng,lossCause:'party wiped',log:[]};
}
function targetEnemy(b,p){const targets=alive(b.enemies);if(!targets.length)return null;if(p.focus>.8)return targets.sort((a,c)=>a.hp-c.hp)[0];return b.rng()<p.focus?targets[0]:pick(b.rng,targets)}
function hit(target,dmg,b,fixed=false){const before=target.hp,rolled=fixed?Math.max(0,Math.round(dmg)):variance(b.rng,dmg);target.hp=Math.max(0,target.hp-rolled);return before-target.hp}
function basic(actor,target,b,mult=2){let crit=b.rng()<actor.luck/100;let raw=actor.atk*mult-target.def;if(crit)raw*=1.5;return{damage:hit(target,raw,b),crit}}
function reviveWithJam(b,key){const dead=b.party.filter(x=>x.hp<=0);if(!dead.length||!b.inv.jam)return null;if(key==='custom'&&dead.length<2)return null;const t=dead[0];t.hp=Math.round(t.maxHp*.5);b.inv.jam--;return t}
function playerAction(actor,b,p,key,setup){
  if(actor.hp<=0)return 'is Toast';
  const revived=reviveWithJam(b,key);if(revived)return `uses Life Jam on ${revived.name}`;
  const low=lowest(b.party);
  if(actor.id==='hero'&&low&&low.hp/low.maxHp<p.heal&&actor.juice>=10){actor.juice-=10;low.hp=Math.min(low.maxHp,low.hp+Math.round(low.maxHp*.75));return `uses Cook on ${low.name}`}
  if(low&&low.hp/low.maxHp<p.item&&b.inv.candy>0){low.hp=Math.min(low.maxHp,low.hp+30);b.inv.candy--;return `uses Candy on ${low.name}`}
  if(actor.juice<8&&b.inv.juice>0&&p!==POLICY.custom&&b.rng()<p.item){actor.juice=Math.min(actor.maxJuice,actor.juice+20);b.inv.juice--;return 'uses Apple Juice'}
  const t=targetEnemy(b,p);if(!t)return 'has no target';
  if(actor.id==='aubrey'&&setup.headbutt&&actor.juice>=5&&actor.hp/actor.maxHp>(p.headbuttMinHp??.32)&&b.rng()<p.headbutt){actor.juice-=5;const recoil=Math.min(actor.hp-1,Math.floor(actor.maxHp*.2));actor.hp-=recoil;const r=basic(actor,t,b,2.5);return `uses Headbutt on ${t.name} for ${r.damage} damage${r.crit?' (critical)':''}; takes ${recoil} recoil`}
  if(actor.id==='kel'&&actor.juice>=15&&b.rng()<p.skill){actor.juice-=15;const damage=hit(t,(actor.level>=9?actor.spd*1.5:actor.atk*2.5)-t.def,b);return `uses ${actor.level>=9?"Run 'n Gun":'Rebound'} on ${t.name} for ${damage} damage`}
  if(actor.id==='omori'&&key==='custom'&&actor.level>=3&&actor.juice>=13){actor.juice-=13;const damage=hit(t,(actor.atk*1.5-t.def)*1.5,b);return `uses Stab on ${t.name} for ${damage} damage (guaranteed critical)`}
  if(actor.id==='omori'&&actor.level>=10&&actor.juice>=30&&b.rng()<p.skill*.35){actor.juice-=30;const hits=[];for(let i=0;i<3&&t.hp>0;i++)hits.push(basic(actor,t,b,2).damage);return `uses Hack Away on ${t.name} for ${hits.reduce((a,c)=>a+c,0)} damage (${hits.join(' + ')})`}
  if(actor.id==='omori'&&actor.level>=5&&actor.juice>=10&&b.rng()<p.skill){actor.juice-=10;const r=basic(actor,t,b,2.5);return `uses Bread Slice on ${t.name} for ${r.damage} damage${r.crit?' (critical)':''}`}
  if(actor.id==='hero'&&actor.juice>=25&&b.rng()<p.skill*.25&&t.kind==='spaceboy'){actor.juice-=25;t.atkDown=Math.max(t.atkDown||0,2);return `uses Smile on ${t.name}`}
  const r=basic(actor,t,b);let action=`attacks ${t.name} for ${r.damage} damage${r.crit?' (critical)':''}`;const boss=['download','spaceboy'].includes(setup.encounter),releaseReady=actor.id==='omori'&&b.energy>=10&&alive(b.party).length===4&&(key==='best'||(key==='custom'&&boss));if(releaseReady){b.energy=0;const hits=alive(b.enemies).map(e=>`${e.name} ${hit(e,300,b,true)}`);for(const friend of alive(b.party)){friend.atk*=1.25;friend.def*=1.25;friend.spd*=1.25;friend.luck*=1.25}return action+` → releases Energy: ${hits.join(', ')} damage; party stats rise`}if(b.energy>=3&&b.rng()<p.follow){b.energy-=3;const bonus=actor.id==='kel'?actor.atk+24-t.def:actor.id==='omori'?actor.atk+actor.luck-t.def:actor.atk*1.4-t.def,followDamage=hit(t,bonus,b);action+=actor.id==='kel'?` → Passes to Aubrey for ${followDamage} damage`:actor.id==='omori'?` → Trips for ${followDamage} damage`:` → follow-up for ${followDamage} damage`}return action
}
function damageParty(target,raw,b,fixed=false){const before=target.hp,dmg=fixed?Math.round(raw):variance(b.rng,Math.max(1,raw));target.hp=Math.max(0,target.hp-dmg);b.energy=Math.min(10,b.energy+1);return before-target.hp}
function spaceboyAction(e,b){
  const a=e.atk*Math.max(.55,1-(e.atkDown||0)*.12);const hp=e.hp/e.maxHp;const phase=hp<=.25?3:hp<=.5?2:hp<=.75?1:0;const rage=[1,1.3,1.5,2][phase];
  const targets=alive(b.party);if(!targets.length)return;const one=pick(b.rng,targets);
  if(b.rng()<.35){const damage=damageParty(one,a*2*rage+5-one.def,b);return `attacks ${one.name} for ${damage} damage`}
  if(hp<=.25){const hits=[];for(let i=0;i<4;i++){const now=alive(b.party);if(!now.length)break;const target=pick(b.rng,now),damage=damageParty(target,20,b,true);hits.push(`${target.name} ${damage}`)}return `uses Bullet Hell: ${hits.join(', ')}`}
  if(b.rng()<.30)return 'does nothing';
  if(b.rng()<.30)return 'uses Angsty Song (non-damage effect not yet modeled)';
  if(b.rng()<.30){const hits=alive(b.party).map(t=>`${t.name} ${damageParty(t,a*2*rage-t.def,b)}`);return `uses Angry Song: ${hits.join(', ')}`}
  const damage=damageParty(one,a*2.5*rage-one.def,b);return `uses Space Laser on ${one.name} for ${damage} damage`
}
function enemyAction(e,b){
  if(e.hp<=0)return 'is defeated';if(e.kind==='spaceboy')return spaceboyAction(e,b);
  if(e.kind==='download'){if(b.turn===3||b.turn>=6){const hits=alive(b.party).map(t=>`${t.name} ${damageParty(t,t.maxHp*.8,b,true)}`);return `uses CRASH: ${hits.join(', ')} damage`}return b.turn===1?'is at 99%':'is still at 99%'}
  const t=pick(b.rng,alive(b.party));if(!t)return 'has no target';if(b.rng()<.55){const damage=damageParty(t,e.atk*2-t.def,b);return `attacks ${t.name} for ${damage} damage`}if(b.rng()<.35)return 'does nothing';const damage=damageParty(t,e.atk*3-t.def,b);return `uses Bunny Beam on ${t.name} for ${damage} damage`
}
function oneBattle(setup,key,seed,withTrace=false){
  const b=makeBattle(setup,rng32(seed));const base=POLICY[key];let p={...base};if(setup.encounter==='download'&&key==='best')p={...p,heal:0,item:0,skill:1,follow:.05,headbutt:.55};if(['download','spaceboy'].includes(setup.encounter)&&key==='custom')p={...p,heal:.60,item:.35,follow:.08,headbutt:.62,headbuttMinHp:.55};
  while(alive(b.party).length&&alive(b.enemies).length&&b.turn<100){b.turn++;const queue=[...alive(b.party).map(x=>({side:'p',x,spd:x.spd})),...alive(b.enemies).map(x=>({side:'e',x,spd:x.spd}))].sort((a,c)=>c.spd-a.spd+(b.rng()-.5)*.02);for(const q of queue){if(!alive(b.party).length||!alive(b.enemies).length)break;const action=q.side==='p'?playerAction(q.x,b,p,key,setup):enemyAction(q.x,b);if(withTrace)b.log.push({turn:b.turn,actor:q.x.name,action,energy:b.energy,party:b.party.map(x=>({name:x.name,hp:x.hp,max:x.maxHp,juice:x.juice})),enemies:b.enemies.map(x=>({name:x.name,hp:x.hp,max:x.maxHp}))})}}
  return{win:alive(b.enemies).length===0,turns:b.turn,survivors:alive(b.party).length,trace:b.log};
}
function wilson(w,n){if(!n)return[0,0];const z=1.96,p=w/n,d=1+z*z/n,c=(p+z*z/(2*n))/d,m=z*Math.sqrt((p*(1-p)+z*z/(4*n))/n)/d;return[Math.max(0,c-m),Math.min(1,c+m)]}
export function simulate(setup,key,trials,seed){let wins=0,survivors=0;const turns=[];for(let i=0;i<trials;i++){const r=oneBattle(setup,key,(seed+i*2654435761+(key.charCodeAt(0)<<16))>>>0);if(r.win)wins++;turns.push(r.turns);survivors+=r.survivors}turns.sort((a,b)=>a-b);return{key,name:POLICY[key].name,wins,trials,rate:wins/trials,ci:wilson(wins,trials),medianTurns:turns[Math.floor(turns.length/2)],avgSurvivors:survivors/trials}}
export function runAll(setup,trials,seed){return['suboptimal','decent','best','custom'].map(k=>simulate(setup,k,trials,seed))}
export function rollScenario(setup,key,seed){const r=oneBattle(setup,key,seed,true);return{policy:POLICY[key].name,seed,win:r.win,turns:r.turns,trace:r.trace}}
